import React, { useState } from 'react';
import { FiSearch, FiCheckCircle, FiClock, FiXCircle } from 'react-icons/fi';
import './dashboard.css';

const TransactionsManagement = () => {
  const [searchTerm, setSearchTerm] = useState('');
  const [filter, setFilter] = useState('all');

  const transactions = [
    { id: 'TXN-001', user: 'Sarah Johnson', type: 'Subscription', amount: '$29.99', status: 'completed', date: '2026-04-02', method: 'Credit Card' },
    { id: 'TXN-002', user: 'Michael Chen', type: 'Premium Upgrade', amount: '$99.99', status: 'completed', date: '2026-04-02', method: 'PayPal' },
    { id: 'TXN-003', user: 'Emma Davis', type: 'Job Posting', amount: '$19.99', status: 'pending', date: '2026-04-02', method: 'Mobile Money' },
    { id: 'TXN-004', user: 'James Wilson', type: 'Featured Job', amount: '$49.99', status: 'completed', date: '2026-04-01', method: 'Bank Transfer' },
    { id: 'TXN-005', user: 'Lisa Anderson', type: 'Refund', amount: '-$29.99', status: 'completed', date: '2026-04-01', method: 'Credit Card' },
    { id: 'TXN-006', user: 'David Brown', type: 'Subscription', amount: '$29.99', status: 'failed', date: '2026-03-31', method: 'Credit Card' },
    { id: 'TXN-007', user: 'Sophie Martin', type: 'Premium Upgrade', amount: '$99.99', status: 'completed', date: '2026-03-31', method: 'PayPal' },
    { id: 'TXN-008', user: 'Alex Johnson', type: 'Job Posting', amount: '$19.99', status: 'completed', date: '2026-03-30', method: 'Mobile Money' },
  ];

  const filteredTransactions = transactions.filter(t => {
    const matchesSearch = t.user.toLowerCase().includes(searchTerm.toLowerCase()) ||
                         t.id.toLowerCase().includes(searchTerm.toLowerCase());
    const matchesFilter = filter === 'all' || t.status === filter;
    return matchesSearch && matchesFilter;
  });

  const getStatusBadge = (status) => {
    const styles = {
      completed: { bg: '#00d973', icon: FiCheckCircle },
      pending: { bg: '#ffd700', icon: FiClock },
      failed: { bg: '#ff6b6b', icon: FiXCircle },
    };
    return styles[status] || styles.completed;
  };

  return (
    <div className="panel">
      <div className="panel-title">Transactions Panel</div>
      
      {/* Summary Stats */}
      <div style={{ display: 'flex', gap: 16, marginBottom: 20, flexWrap: 'wrap' }}>
        <div style={{ padding: '4px 12px', background: 'rgba(0, 217, 115, 0.1)', border: '0.5px solid rgba(0, 217, 115, 0.3)', borderRadius: 6, minWidth: 'fit-content', textAlign: 'center' }}>
          <div style={{ fontSize: 10, color: '#8696a0', marginBottom: 1 }}>Total Transactions</div>
          <div style={{ fontSize: 16, fontWeight: 'bold', color: '#00d973' }}>{transactions.length}</div>
        </div>
        <div style={{ padding: '4px 12px', background: 'rgba(0, 217, 115, 0.1)', border: '0.5px solid rgba(0, 217, 115, 0.3)', borderRadius: 6, minWidth: 'fit-content', textAlign: 'center' }}>
          <div style={{ fontSize: 10, color: '#8696a0', marginBottom: 1 }}>Completed</div>
          <div style={{ fontSize: 16, fontWeight: 'bold', color: '#00d973' }}>{transactions.filter(t => t.status === 'completed').length}</div>
        </div>
        <div style={{ padding: '4px 12px', background: 'rgba(255, 215, 0, 0.1)', border: '0.5px solid rgba(255, 215, 0, 0.3)', borderRadius: 6, minWidth: 'fit-content', textAlign: 'center' }}>
          <div style={{ fontSize: 10, color: '#8696a0', marginBottom: 1 }}>Pending</div>
          <div style={{ fontSize: 16, fontWeight: 'bold', color: '#ffd700' }}>{transactions.filter(t => t.status === 'pending').length}</div>
        </div>
        <div style={{ padding: '4px 12px', background: 'rgba(255, 107, 107, 0.1)', border: '0.5px solid rgba(255, 107, 107, 0.3)', borderRadius: 6, minWidth: 'fit-content', textAlign: 'center' }}>
          <div style={{ fontSize: 10, color: '#8696a0', marginBottom: 1 }}>Failed</div>
          <div style={{ fontSize: 16, fontWeight: 'bold', color: '#ff6b6b' }}>{transactions.filter(t => t.status === 'failed').length}</div>
        </div>
      </div>

      {/* Filters */}
      <div style={{ display: 'flex', gap: 8, marginBottom: 12, flexWrap: 'wrap', alignItems: 'center' }}>
        <div style={{ minWidth: 250, position: 'relative' }}>
          <FiSearch style={{ position: 'absolute', left: 8, top: '50%', transform: 'translateY(-50%)', color: '#8696a0' }} />
          <input
            type="text"
            placeholder="Search transactions or users..."
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            className="input"
            style={{ 
              paddingLeft: 32, 
              width: '100%', 
              backgroundColor: 'black', 
              color: 'white', 
              fontSize: '13px',
              border: '1px solid transparent',
              borderRadius: '4px',
              transition: 'border-color 0.2s',
              outline: 'none'
            }}
          />
        </div>
        <select
          className="select"
          value={filter}
          onChange={(e) => setFilter(e.target.value)}
          style={{ minWidth: 70, width: 'auto', fontSize: '10px' }}
        >
          <option value="all">All Status</option>
          <option value="completed">Completed</option>
          <option value="pending">Pending</option>
          <option value="failed">Failed</option>
        </select>
      </div>

      {/* Transactions Table */}
      <div style={{ overflowX: 'auto' }}>
        <table className="table">
          <thead>
            <tr>
              <th>#</th>
              <th>Transaction ID</th>
              <th>User</th>
              <th>Type</th>
              <th>Amount</th>
              <th>Status</th>
              <th>Date</th>
              <th>Method</th>
              <th>Action</th>
            </tr>
          </thead>
          <tbody>
            {filteredTransactions.map((txn, idx) => {
              const statusBadge = getStatusBadge(txn.status);
              const StatusIcon = statusBadge.icon;
              return (
                <tr key={txn.id}>
                  <td style={{ width: '5%' }}>{idx + 1}</td>
                  <td style={{ width: '12%' }}><strong>{txn.id}</strong></td>
                  <td style={{ width: '12%' }}>{txn.user}</td>
                  <td style={{ width: '12%' }}>{txn.type}</td>
                  <td style={{ width: '10%', color: txn.amount.startsWith('-') ? '#ff6b6b' : '#00d973', fontWeight: '600' }}>
                    {txn.amount}
                  </td>
                  <td style={{ width: '12%' }}>
                    <span className="badge" style={{ color: statusBadge.bg, display: 'inline-flex', alignItems: 'center', gap: 4, padding: '4px 8px', borderRadius: 4, fontSize: 11 }}>
                      <StatusIcon size={12} /> {txn.status}
                    </span>
                  </td>
                  <td style={{ width: '12%' }}>{txn.date}</td>
                  <td style={{ width: '12%' }}>{txn.method}</td>
                  <td style={{ width: '8%', textAlign: 'center' }}>
                    <div style={{ display: 'flex', gap: 8, alignItems: 'center', justifyContent: 'center', flexWrap: 'wrap' }}>
                      <button
                        className="btn"
                        style={{ padding: '4px 8px', fontSize: '12px', whiteSpace: 'nowrap', width: 'auto', minWidth: 'auto', maxWidth: 'max-content' }}
                      >
                        Details
                      </button>
                    </div>
                  </td>
                </tr>
              );
            })}
          </tbody>
        </table>
      </div>

      {/* Pagination Info */}
      <div style={{ display: 'flex', justifyContent: 'center', alignItems: 'center', marginTop: 16, paddingTop: 12, borderTop: '1px solid rgba(134, 150, 160, 0.2)' }}>
        <div style={{ fontSize: 12, color: '#8696a0' }}>
          {filteredTransactions.length} of {transactions.length} transactions
        </div>
      </div>
    </div>
  );
};

export default TransactionsManagement;
